158|/** Label-over-input (product forms) vs label-beside-control (dense inspectors). */
159|export type FormFieldLayout = 'stack' | 'side';
160|
161|const FormFieldLayoutContext = React.createContext<FormFieldLayout>('stack');
162|
163|export const FormFieldLayoutProvider: React.FC<{
164|  layout: FormFieldLayout;
165|  children: React.ReactNode;
166|}> = ({ layout, children }) => (
167|  <FormFieldLayoutContext.Provider value={layout}>{children}</FormFieldLayoutContext.Provider>
168|);
